sys_script_include.script:
// Role: the ONLY place that decides who may see or do what. The app has no ACLs, so every screen and every
//       action goes through these checks on the server.
//       House rules: the compliance team (role x_1929776_compli_0.admin) sees everything and reviews evidence;
//       an owner sees only the controls they own; only the OWNER of a control can upload evidence for it.
var CPMAccess = Class.create();
CPMAccess.prototype = {
  initialize: function() {
    this.userId = gs.getUserID();
  },

  // Role: true for members of the compliance team.
  isAdmin: function() {
    return gs.hasRole('x_1929776_compli_0.admin');
  },

  // Role: is the current user the owner of this mapping? This is the only test for uploading, admins included.
  isOwnerOf: function(mapping) {
    return !!mapping.getValue('owner') && mapping.getValue('owner') == this.userId;
  },

  // Role: may the current user look at this mapping and its evidence? The team always, owners only their own.
  canSee: function(mapping) {
    return this.isAdmin() || this.isOwnerOf(mapping);
  },

  // Role: the ids of the CIs and services the current user owns. Drives "I only see my own services".
  ownedTargetIds: function() {
    var ids = [];
    var ga = new GlideAggregate('x_1929776_compli_0_mapping');
    ga.addQuery('owner', this.userId);
    ga.addQuery('active', true);
    ga.addAggregate('COUNT');
    ga.groupBy('target');
    ga.query();
    while (ga.next()) ids.push(ga.getValue('target'));
    return ids;
  },

  // Role: may the current user open the page of this CI or service? The team always, owners only if they own a control on it.
  canViewTarget: function(targetId) {
    if (this.isAdmin()) return true;
    var gr = new GlideRecord('x_1929776_compli_0_mapping');
    gr.addQuery('target', targetId);
    gr.addQuery('owner', this.userId);
    gr.setLimit(1);
    gr.query();
    return gr.hasNext();
  },

  type: 'CPMAccess'
};
